INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47911, 'Ezekiel 3:12', 'Ezekiel', 3, 12, 'بیا د خدای روح زه پورته کړم او د شا له خوا نه مې د یو لوړ اواز غرهار واورېد چې ویل یې: «د څښتن د جلال ثنا او صفت دې وي د هغه د اوسېدلو په ځای کې!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_12.mp3', '', 1761754199, 1761754199),
(47912, 'Ezekiel 3:13', 'Ezekiel', 3, 13, 'دا د هغو ژوندیو مخلوقاتو د وزرونو د وهلو اواز ؤ چې یو د بل سره لګېدل او د هغو ارابو شورماشور ؤ چې د دوی په څنګ کې وې. هغه شورماشور د یوې لویې زلزلې په شان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_13.mp3', '', 1761754199, 1761754199),
(47913, 'Ezekiel 3:14', 'Ezekiel', 3, 14, 'ما د څښتن حضور د هغه په ټول قدرت سره احساس کړ او کله چې د هغه روح زه پورته کړم او د ځان سره یې یووړم، نو زه نا‌ارامه او په قهر شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_14.mp3', '', 1761754199, 1761754199),
(47914, 'Ezekiel 3:15', 'Ezekiel', 3, 15, 'نو زه د تل‌ابیب کلي ته چې جلاوطنه خلک د کیبار د سیند په څنګ کې اوسېدل، راغلم او هلته د هغوی په منځ کې اووه ورځې سخت خفه کښېناستم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_15.mp3', '', 1761754199, 1761754199),
(47915, 'Ezekiel 3:16', 'Ezekiel', 3, 16, 'وروسته له اوو ورځو څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_16.mp3', '', 1761754199, 1761754199),
(47916, 'Ezekiel 3:17', 'Ezekiel', 3, 17, '«ای فاني انسانه، ته مې د اسراییلو د قوم دپاره پهره‌دار ټاکلی یي. زه چې تاته کوم خبرداری درکوم باید هغوی ته یې ورسوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_17.mp3', '', 1761754199, 1761754199),
(47917, 'Ezekiel 3:18', 'Ezekiel', 3, 18, 'که زه یو بدکاره انسان ته خبرداری ورکړم چې هرومرو مړ کیږي او ته زما خبرداری هغه ته ونه رسوې او ورته ونه وایې چې د خپلو بدو کارونو څخه توبه وباسې ترڅو د هغه ژوند وژغورل شي، هغه به د خپلې ګناه له امله مړ شي، نو تا به د هغه د مړینې مسوول وګڼم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_18.mp3', '', 1761754199, 1761754199),
(47918, 'Ezekiel 3:19', 'Ezekiel', 3, 19, 'خو که چېرې ته یو بدکاره انسان ته خبرداری ورکړې او هغه بیاهم توبه ونه باسي او د ګناه کولو څخه لاس وانخلي، نو هغه به د خپلې ګناه له امله مړ شي، خو تا به د مړینې څخه ځان ژغورلی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_19.mp3', '', 1761754199, 1761754199),
(47919, 'Ezekiel 3:20', 'Ezekiel', 3, 20, 'که چېرې یو نېک انسان له سمې لارې څخه واوړي او په بدو کارونو پیل وکړي او زه هغه د یو خطرناکه حالت سره مخامخ کړم، نو که چېرې ته ورته خبرداری ورنه کړې، هغه به د خپلي ګناه له امله مړ شي. زه به د هغه ټول ښه کارونه هېر کړم، خو تا به د هغه د مړینې مسوول وګڼم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_20.mp3', '', 1761754199, 1761754199),
(47920, 'Ezekiel 3:21', 'Ezekiel', 3, 21, 'خو که چېرې ته یو نېک انسان ته خبرداری ورکړې چې ګناه مه کوه او هغه ستا خبره ومني او ګناه پرېږدي، نو هغه به په پوره باور سره ژوندی پاتې شي. په دې خاطر چې هغه خبرداری قبول کړ، نو تا به د مړینې څخه ځان ژغورلی وي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_21.mp3', '', 1761754199, 1761754199),
(47921, 'Ezekiel 3:22', 'Ezekiel', 3, 22, 'د څښتن د حضور زور مې په خپل بدن کې احساس کړ او ماته یې وویل: «پاڅېږه، دباندې ووځه او درې ته لاړ شه. زه به په هغه ځای کې ستا سره خبرې وکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_22.mp3', '', 1761754199, 1761754199),
(47922, 'Ezekiel 3:23', 'Ezekiel', 3, 23, 'نو زه پاڅېدم، دباندې ووتلم او درې ته لاړم او هلته مې د څښتن جلال ولیده لکه څنګه چې مې د خابور د سیند په غاړه لیدلی ؤ. بیا زه پړمخې په ځمکه ولوېدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_23.mp3', '', 1761754199, 1761754199),
(47923, 'Ezekiel 3:24', 'Ezekiel', 3, 24, 'خو د خدای روح په ما کې داخل شو او زه یې په پښو ودرولم. بیا څښتن راته وویل: «کور ته لاړ شه او خپل ځان دې په کور کې بندي کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_24.mp3', '', 1761754199, 1761754199),
(47924, 'Ezekiel 3:25', 'Ezekiel', 3, 25, 'ای فاني انسانه، ته به په پړو وتړل شې او وبه نه شې کولای چې دباندې له خلکو سره یوځای شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_25.mp3', '', 1761754199, 1761754199),
(47925, 'Ezekiel 3:26', 'Ezekiel', 3, 26, 'زه به ستا ژبه په تالو پورې ونښلوم او تا به ګونګی کړم، ترڅو ونه شې کولای هغوی ورټې، ځکه چې هغوی سرکښه قوم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_26.mp3', '', 1761754199, 1761754199),
(47926, 'Ezekiel 3:27', 'Ezekiel', 3, 27, 'خو کله چې زه بیا ستا سره خبرې وکړم او تاته بېرته د خبرو کولو توان درکړم، نو څه چې زه څښتن تعالی درته وایم، ته به یې هغوی ته ووایې. ځینې خلک به ستا خبرو ته غوږ ونیسي او ځینې به یې د اورېدلو نه انکار وکړي، ځکه چې هغه سرکښه قوم دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel3_verse_27.mp3', '', 1761754199, 1761754199),
(47927, 'Isaiah 19:1', 'Isaiah', 19, 1, 'د مصر په هکله پیغام: ګورئ، څښتن په تېزه ورېځ سپور او مصر ته راروان دی. د مصر بتان د هغه په حضور کې لړزیږي او د مصر خلک د وېرې له امله بې سده کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_1.mp3', '', 1761754199, 1761754199),
(47928, 'Isaiah 19:2', 'Isaiah', 19, 2, 'څښتن وایي: «زه به په مصر کې کورنۍ جګړه رامنځته کړم او ورور به د ورور په وړاندې او ګاونډی به د ګاونډي په ضد راوپاروم. ښارونه به د یو بل په وړاندې او پاچاهۍ به د پاچاهۍ په ضد وجنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_2.mp3', '', 1761754199, 1761754199),
(47929, 'Isaiah 19:3', 'Isaiah', 19, 3, 'زه غواړم چې د مصریانو نقشې شنډې او د هغوی روحیه کمزورې کړم. هغوی به د خپلو بتانو څخه د مرستې غوښتنه وکړي او د جادوګرانو، فال کتونکو او د مړو د ارواحګانو څخه به مشوره واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_3.mp3', '', 1761754199, 1761754199),
(47930, 'Isaiah 19:4', 'Isaiah', 19, 4, 'زه به مصریان یو ظالم او بې رحمه پاچا ته په لاس ورکړم چې په هغوی باندې پاچاهي وکړي. دا زه یعنې مطلق قادر څښتن داسې وایم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_4.mp3', '', 1761754199, 1761754199),
(47931, 'Isaiah 19:5', 'Isaiah', 19, 5, 'د نیل د سیند اوبه به لږې شي او د وخت په تېرېدلو سره به وچې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_5.mp3', '', 1761754199, 1761754199),
(47932, 'Isaiah 19:6', 'Isaiah', 19, 6, 'د سیند ویالې به مخ په وچېدلو شي او بد بوی به ورڅخه پورته شي. لوخې او د نیل د سیند د غاړې واښه به مړاوي شي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_6.mp3', '', 1761754199, 1761754199),
(47933, 'Isaiah 19:7', 'Isaiah', 19, 7, 'د نیل د سیند د غاړې لوخې او ټول کرل شوي فصلونه به وچ شي او هوا ته به والوزي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_7.mp3', '', 1761754199, 1761754199),
(47934, 'Isaiah 19:8', 'Isaiah', 19, 8, 'ماهيګیران به چې د نیل په سیند کې په چنګک باندې ماهیان نیسي، ویر کوي. هغه څوک چې په جال باندې ماهیان نیسي، هغه به خپل همت له لاسه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_8.mp3', '', 1761754199, 1761754199),
(47935, 'Isaiah 19:9', 'Isaiah', 19, 9, 'د کتان تیاروونکي به ناامیده شي او اوبدونکي به یې اندېښمن شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_9.mp3', '', 1761754199, 1761754199),
(47936, 'Isaiah 19:10', 'Isaiah', 19, 10, 'ټول کتان جوړوونکي به سخت غمجن او ټول کارګران به خواشیني شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_10.mp3', '', 1761754199, 1761754199),
(47937, 'Isaiah 19:11', 'Isaiah', 19, 11, 'د صوعن د ښار مشران ډېر بې عقله دي! د فرعون ډېر هوښیار مشاوران احمقانه مشوره ورکوي! نو هغوی څنګه کولای شي چې فرعون ته ووایي: «مونږ عالمان او د پخوانیو پاچاهانو اولاده یو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_11.mp3', '', 1761754199, 1761754199),
(47938, 'Isaiah 19:12', 'Isaiah', 19, 12, 'ای فرعونه، ستا هغه هوښیار مشاوران چېرته دي؟ هغوی دې تاته ووایي چې مطلق قادر څښتن د مصر په وړاندې څه اراده لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_12.mp3', '', 1761754199, 1761754199),
(47939, 'Isaiah 19:13', 'Isaiah', 19, 13, 'د صوعن او ممفیس مشران بې عقله دي او هغوی خپل ځانونه غولولي دي. د طایفو مشرانو د مصر خلک بې لارې کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_13.mp3', '', 1761754199, 1761754199),
(47940, 'Isaiah 19:14', 'Isaiah', 19, 14, 'څښتن د هغوی فکرونه مغشوش کړل چې ګډې وډې مشورې ورکړي. په نتیجه کې مصریان چې هرڅه کوي هغه غلط وي او داسې کاږه واږه ځي لکه کوم نشه سړی چې په خپلو کانګو ښوییږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_14.mp3', '', 1761754199, 1761754199),
(47941, 'Isaiah 19:15', 'Isaiah', 19, 15, 'په مصر کې هېڅوک، که هغه شتمن وي یا غریب، که لوی یا کوچنی، نه شي کولای چې د خلکو سره مرسته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_15.mp3', '', 1761754199, 1761754199),
(47942, 'Isaiah 19:16', 'Isaiah', 19, 16, 'په هغه ورځ کله چې مصریان وویني چې مطلق قادر څښتن خپل لاس هغوی ته د سزا ورکولو دپاره اوچت کړی دی، نو هغوی به د ښځو په شان له وېرې ولړزیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_16.mp3', '', 1761754199, 1761754199),
(47943, 'Isaiah 19:17', 'Isaiah', 19, 17, 'مصریان به د یهودا د خاورې د نوم په اورېدلو په وېره کې وي، دا په دې خاطر چې مطلق قادر څښتن د هغوی په وړاندې داسې اراده لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_17.mp3', '', 1761754199, 1761754199),
(47944, 'Isaiah 19:18', 'Isaiah', 19, 18, 'په هغه ورځ به د مصر په پنځو ښارونو کې خلک په عبراني ژبه خبرې وکړي او د دې ځایونو خلک به د څښتن تعالی سره د وفادارۍ قسم وکړي. له دې ښارونو څخه یو به د «لمر د ښار» په نوم یاد شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_18.mp3', '', 1761754199, 1761754199),
(47945, 'Isaiah 19:19', 'Isaiah', 19, 19, 'په هغه ورځ به د مصر د هېواد په منځنۍ برخه کې د قربانۍ ځای او د مصر په سرحد کې به یوه د تیږو یادګاري ستنه څښتن ته وقف شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_19.mp3', '', 1761754199, 1761754199),
(47946, 'Isaiah 19:20', 'Isaiah', 19, 20, 'هغوی به په مصر کې د مطلق قادر څښتن د حضور نښې وي. کله چې د هغه ځای په خلکو ظلم کیږي او د مرستې دپاره څښتن ته زارۍ کوي نو څښتن به د مصریانو د دفاع او ژغورلو دپاره یو ژغورونکی ورولېږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_20.mp3', '', 1761754199, 1761754199),
(47947, 'Isaiah 19:21', 'Isaiah', 19, 21, 'څښتن به خپل ځان د مصر خلکو ته ورښکاره کړي او بیا به مصریان هغه د خپل خدای په توګه وپېژني، د هغه عبادت به وکړي او هغه ته به قربانۍ او نذرانې وړاندې کړي. هغوی به د څښتن حضور ته د نذرونو وعده وکړي او خپلې وعدې به پوره کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_21.mp3', '', 1761754199, 1761754199),
(47948, 'Isaiah 19:22', 'Isaiah', 19, 22, 'څښتن به لومړی مصریانو ته سزا ورکړي، خو وروسته به بیا هغوی ته شفا ورکړي. هغوی به څښتن ته رجوع وکړي او هغه به د هغوی دعاګانې قبولې کړي او هغوی ته به روغتیا ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_22.mp3', '', 1761754199, 1761754199),
(47949, 'Isaiah 19:23', 'Isaiah', 19, 23, 'په هغه ورځ به د مصر او اشور ترمنځ یوه لویه لاره جوړه شي. د دواړو هېوادونو خلک به یو بل سره تګ او راتګ وکړي او دواړه هېوادونه به په ګډه د څښتن عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_23.mp3', '', 1761754199, 1761754199),
(47950, 'Isaiah 19:24', 'Isaiah', 19, 24, 'په هغه ورځ به اسراییل له مصر او اشور سره ملګری شي او دا درې هېوادونه به د ټولې نړۍ دپاره د برکت سبب وګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_24.mp3', '', 1761754199, 1761754199),
(47951, 'Isaiah 19:25', 'Isaiah', 19, 25, 'مطلق قادر څښتن به هغوی ته برکت ورکړي او وبه وایي: «ای زما خلکو مصریانو، ای زما مخلوقه اشوریانو او ای زما غوره شوی قومه اسراییله، زه تاسو ټولو ته برکت درکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah19_verse_25.mp3', '', 1761754199, 1761754199),
(47952, 'Lamentations 1:1', 'Lamentations', 1, 1, 'افسوس، افسوس، هغه ښاريه څنګه يواځې پاتې شوه، چې په يو وخت کښې هغه د خلقو نه ډکه وه. هغه څنګه لکه د يوې کونډې په شان شوه، هغه چې په يو وخت کښې په قومونو کښې ډېره لويه وه. د نورو ښارونو په نسبت هغه لکه د شهزادګۍ وه خو اوس هغه غريبه غلامه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_1.mp3', '', 1761754199, 1761754199),
(47953, 'Lamentations 1:2', 'Lamentations', 1, 2, 'هغه ټوله شپه په سلګو او ژړا تېروى، او په مخ يې د اوښکو سېلابونه بهيږى. په ټولو عاشقانو کښې يې يو هم پاتې نۀ وو، چې ورله تسلى ورکړى. د هغې ټولو دوستانو د هغې سره بې‌وفائى کړې ده، او د هغې دشمنان جوړ شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_2.mp3', '', 1761754199, 1761754199),
(47954, 'Lamentations 1:3', 'Lamentations', 1, 3, 'يهوداه جلاوطن کړے شو، د ډېرو سختو مشقتونو سره هغه د نورو مُلکونو په مينځ کښې اوسيږى، او د اوسېدو دپاره هغه د آرام ځائ نۀ لرى. د هغۀ دشمنانو هغه راګېر کړو، او هغۀ ته د تښتېدو موقع نۀ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_3.mp3', '', 1761754199, 1761754199),
(47955, 'Lamentations 1:4', 'Lamentations', 1, 4, 'صيون ته د تلو لارې خالى دى او ماتم کوى، څوک هم ورته اوس د اخترونو دپاره نۀ راځى. د ښار دروازې ټولې خاموشه شوې دى، او د دې اِمامان اسويلى کوى. د هغې پېغلې غمژنې دى، او د هغې تکليفونه تراخۀ دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_4.mp3', '', 1761754199, 1761754199),
(47956, 'Lamentations 1:5', 'Lamentations', 1, 5, 'د هغې دشمنان په هغې اختيارمن شول، او د هغې دشمنان آرام او پُرسکونه ژوند تېروى. مالِک خُدائ داسې ځکه وکړل، چې سرکشى يې ډېره وه. د هغې ماشومان ونيولے شول، او لرې مُلک ته جلاوطن کړے شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_5.mp3', '', 1761754199, 1761754199),
(47957, 'Lamentations 1:6', 'Lamentations', 1, 6, 'د لور صيون ټوله لوئى ختمه شوه، او د هغې نه ټول شان او شوکت لاړو. شهزادګان يې لکه د هغه هوسو په شان شول، چې د څرن ځائ موندلے نۀ شى. هغوئ خو دومره کمزورى شوى وُو، چې د ښکارى نه تښتېدلے نۀ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_6.mp3', '', 1761754199, 1761754199),
(47958, 'Lamentations 1:7', 'Lamentations', 1, 7, 'يروشلم ښاريې ته هغه وخت ياد دے په کومو ورځو کښې چې زورېدلې او سرګردانه وه، ټول قيمتى څيزونه ورته ياد وُو کوم چې پخوا هغې سره وُو. کله چې هغه د دشمن لاسونو کښې پرېوته، او داسې هيڅ څوک نۀ وُو چې د هغې مدد وکړى، دشمن د هغې د شکست تماشه کوله او د هغې په راغورزېدلو خوشحاله شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_7.mp3', '', 1761754199, 1761754199),
(47959, 'Lamentations 1:8', 'Lamentations', 1, 8, 'يروشلم ښاريې سخته ګناه وکړله او د هغې په وجه پليته شوه. هر چا چې د هغې عزت کولو اوس ورته سپک ګورى ځکه چې دوئ هغه بربنډه او عاجزه وليده. هغه په خپله په زوره زبيرګى کوى او د شرم نه خپل مخ په لاسونو پټوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_8.mp3', '', 1761754199, 1761754199),
(47960, 'Lamentations 1:9', 'Lamentations', 1, 9, 'د هغې په لمن د ناپاکۍ داغونه لګېدلى وُو، هغې د خپل اَنجام څۀ سوچ نۀ کولو، د هغې راغورزېدل وحشتناکه وو، څوک داسې نۀ وو چې هغې له تسلى ورکړى. ”مالِکه خُدايه، زما دې تکليفونو ته وګوره، ځکه چې دشمن په ما غالب شوے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_9.mp3', '', 1761754199, 1761754199),
(47961, 'Lamentations 1:10', 'Lamentations', 1, 10, 'دشمن خپل لاسونه وراوږدۀ کړل او د هغې ټول قيمتى څيزونه يې لوټ کړل. هغې په خپله وليدل چې غېر قومونه د هغې مقدس ځائ ته داخل شول، اګر چې تا دغه خلق خپل جماعت ته د داخلېدو نه منع کړى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_10.mp3', '', 1761754199, 1761754199),
(47962, 'Lamentations 1:11', 'Lamentations', 1, 11, 'ټولو خلقو يې د روټۍ په تلاش کښې آهونه کول. د خوراک دپاره يې خپل قيمتى څيزونه خرڅ کړل چې پرې خپل ځانونه ژوندى وساتى. ”اے مالِکه خُدايه، ما ته وګوره زۀ څومره سپکه کړے شوې يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_11.mp3', '', 1761754199, 1761754199),
(47963, 'Lamentations 1:12', 'Lamentations', 1, 12, 'ولې ستاسو دپاره دا هيڅ هم نۀ دى، تاسو ټول څوک چې په لاره تېرېږئ؟ راشئ او وګورئ کۀ چرې زما په شان غم او درد بل چرته وى، کوم چې مالِک خُدائ نازل کړو په هغه ورځ چې هغه په قهر وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_12.mp3', '', 1761754199, 1761754199),
(47964, 'Lamentations 1:13', 'Lamentations', 1, 13, 'هغۀ بره د آسمان نه اور راولېږلو او هغه زما هډوکو ته ورکوز شو. هغۀ زما پښو ته جال وغوړولو او زۀ يې د تلو نه منع کړم. هغۀ زۀ ګنګس کړې پرېښودم او ټوله ورځ بيماره وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_13.mp3', '', 1761754199, 1761754199),
(47965, 'Lamentations 1:14', 'Lamentations', 1, 14, 'زما سرکشى يو جغ پورې تړلے شوې وه او د هغۀ لاسونو دا تړلى وُو. هغه زما په غاړه بار شو او زما زور يې ختم کړو. مالِک زۀ هغوئ ته حواله کړمه د چا چې زۀ مقابله نۀ شم کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_14.mp3', '', 1761754199, 1761754199),
(47966, 'Lamentations 1:15', 'Lamentations', 1, 15, 'مالِک زما ټول فوجيان رد کړل کوم چې ما سره وُو. هغۀ زما خلاف د لښکر اعلان وکړو چې زما ځوانان غوبل کړى. مالِک د يهوداه نيازبين ښار لکه د انګور په شان په لنګرۍ کښې نچوړ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_15.mp3', '', 1761754199, 1761754199),
(47967, 'Lamentations 1:16', 'Lamentations', 1, 16, 'نو په دې کارونو زۀ ژړېږم او سترګو نه مې اوښکې بهيږى. نزدې څوک هم نشته چې ما له تسلى راکړى او يا ما له حوصله راکړى. زما ماشومان غمژن شوى دى ځکه دشمن په ما غالب دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_16.mp3', '', 1761754199, 1761754199),
(47968, 'Lamentations 1:17', 'Lamentations', 1, 17, 'صيون خپل لاسونه د مدد دپاره غزوى، خو هيڅ څوک نشته چې تسلى ورکړى. مالِک خُدائ د يعقوب خلاف حکم وکړو چې د هغۀ ګاونډيان به د هغۀ دشمنان شى. د يروشلم نه د هغوئ په مينځ کښې پليته کپړه جوړه شوې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_17.mp3', '', 1761754199, 1761754199),
(47969, 'Lamentations 1:18', 'Lamentations', 1, 18, '”مالِک خُدائ په حقه دے ځکه ما د هغۀ د حکم نه سرکشى کړې ده. خو اے ټولو خلقو ما ته غوږ شئ، زما غمونو او دردونو ته وګورئ، زما پېغلې ښځې او ځوانان سړى د جلاوطنۍ دپاره بوتلے شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_18.mp3', '', 1761754199, 1761754199),
(47970, 'Lamentations 1:19', 'Lamentations', 1, 19, 'ما خپلو عاشقانو ته آواز وکړو خو هغوئ ما له دوکه راکړه. کله چې اِمامانو او مشرانو د خپلو ځانونو ژوندى ساتلو دپاره خوراک لټولو نو هغوئ په ښاريه کښې مړۀ شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_19.mp3', '', 1761754199, 1761754199),
(47971, 'Lamentations 1:20', 'Lamentations', 1, 20, 'وګوره، اے مالِکه خُدايه زۀ څومره زورېدلې يم او زما روح خفه دے او زړۀ مې ناسازه دے ځکه چې زۀ ډېره سرکشه وم. بهر په کوڅو کښې تُورې د بچو نه خلاصه کړم او په کور کښې دننه هم مرګ راپسې دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_20.mp3', '', 1761754199, 1761754199),
(47972, 'Lamentations 1:21', 'Lamentations', 1, 21, 'هغوئ واورېدل چې ما څنګه زبيرګى کول خو داسې څوک نشته چې ما له تسلى راکړى. زما ټولو دشمنانو زما د تکليفونو په حقله واورېدل او هغوئ خوشحاله شول چې دا تا په ما راوستى دى. هغه ورځ پرې راوله د کومې چې تا اعلان کړے دے نو هغوئ به هم زما په شان شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_21.mp3', '', 1761754199, 1761754199),
(47973, 'Lamentations 1:22', 'Lamentations', 1, 22, 'د هغوئ ټول بدکارونه دې تا ته ښکاره شى. هغوئ له هغسې سزا ورکړه لکه څنګه چې تا ما له زما د ټولې سرکشۍ په وجه راکړې ده. زما کړاونه او زبيرګى زيات دى او زما زړۀ بې‌قراره شوے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/lamentations1_verse_22.mp3', '', 1761754199, 1761754199),
(47974, 'Judges 20:1', 'Judges', 20, 1, 'بیا ټول اسراییلیان په شمال کې د دان څخه په جنوب کې تر بیرشبع پورې او همدارنګه د جلعاد د خاورې څخه په یوه لویه غونډه کې په مصفه کې د څښتن په حضور کې سره راټول شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_1.mp3', '', 1761754199, 1761754199),
(47975, 'Judges 20:2', 'Judges', 20, 2, 'د هغوی شمېر د پیاده عسکرو او مشرانو سره څلور لکه تنه وو چې په هغه ځای کې د څښتن په حضور کې د هغه د قوم په غونډه کې حاضر وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_2.mp3', '', 1761754199, 1761754199),
(47976, 'Judges 20:3', 'Judges', 20, 3, 'بنیامینیان خبر شول چې ټول اسراییلیان په مصفې کې سره راټول شوي دي. اسراییلیانو د وژل شوې ښځې د مېړه څخه پوښتنه وکړه: «مونږ ته ووایه چې دا ناوړه پېښه څنګه رامنځته شوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_3.mp3', '', 1761754199, 1761754199),
(47977, 'Judges 20:4', 'Judges', 20, 4, 'هغه لاوي چې ښځه یې وژل شوې وه، په ځواب کې وویل: «زه او زما وینځه جبعې ته چې د بنیامین په سیمه کې ده، د شپې تېرولو دپاره لاړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_4.mp3', '', 1761754199, 1761754199),
(47978, 'Judges 20:5', 'Judges', 20, 5, 'د شپې د جبعې سړي زما پسې راغلل او کور یې کلابند کړ. هغوی زما د وژلو نیت درلود، خو د دې په ځای هغوی زما وینځه بې عزته کړه او هغه مړه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_5.mp3', '', 1761754199, 1761754199),
(47979, 'Judges 20:6', 'Judges', 20, 6, 'ما د هغې مړی راواخیست او هغه مې ټوټې ټوټې کړ او بیا مې د هغې هره ټوټه د اسراییلو د دولسو قبیلو څخه هرې قبیلې ته ولېږله، ځکه چې د جبعې سړیو په اسراییلو کې داسې سپک او شرمناکه کار کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_6.mp3', '', 1761754199, 1761754199),
(47980, 'Judges 20:7', 'Judges', 20, 7, 'اوس تاسو د اسراییلو ټول قوم باید په خپله پرېکړه وکړئ چې په دې هکله څه وکړو!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_7.mp3', '', 1761754199, 1761754199),
(47981, 'Judges 20:8', 'Judges', 20, 8, 'ټول خلک یوځای پاڅېدل او ویې ویل: «زمونږ څخه به هېڅوک خپلې خېمې یا خپل کور ته نه ځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_8.mp3', '', 1761754199, 1761754199),
(47982, 'Judges 20:9', 'Judges', 20, 9, 'مونږ به داسې کار وکړو چې پچه به واچوو او په جبعې باندې د حملې دپاره به یو څو کسان وټاکو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_9.mp3', '', 1761754199, 1761754199),
(47983, 'Judges 20:10', 'Judges', 20, 10, 'د اسراییلو د ټولو قبیلو څخه به د هرو سلو کسانو څخه لس کسان لښکر ته ډوډۍ رسوي او نور دې لاړ شي او د جبعې خلکو ته دې د هغه ناوړه کار په خاطر سزا ورکړي چې هغوی په اسراییلو کې کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_10.mp3', '', 1761754199, 1761754199),
(47984, 'Judges 20:11', 'Judges', 20, 11, 'نو د اسراییلو ټول سړي د یو مقصد دپاره سره راټول شول چې په ښارګوټي باندې حمله وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_11.mp3', '', 1761754199, 1761754199),
(47985, 'Judges 20:12', 'Judges', 20, 12, 'اسراییلیانو د بنیامین د قبیلې ټولې سیمې ته استازي ولېږل چې ورته ووایي: «تاسو ولې داسې جرم کړی دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_12.mp3', '', 1761754199, 1761754199),
(47986, 'Judges 20:13', 'Judges', 20, 13, 'اوس د جبعې هغه بدکاره سړي مونږ ته تسلیم کړئ، ترڅو هغوی ووژنو او د اسراییلو څخه دا بدي لېرې کړو.» خو بنیامینیانو د خپلو نورو اسراییلي ورونو خبرو ته غوږ ونه نیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_13.mp3', '', 1761754199, 1761754199),
(47987, 'Judges 20:14', 'Judges', 20, 14, 'هغوی د بنیامین د ټولو ښارګوټو څخه راغلل او په جبعې کې سره راټول شول چې د اسراییلیانو په وړاندې جګړه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_14.mp3', '', 1761754199, 1761754199),
(47988, 'Judges 20:17', 'Judges', 20, 17, 'اسراییلیانو څلور لکه روزل شوي عسکر سره راټول کړل چې په هغو کې بنیامینیان شامل نه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_17.mp3', '', 1761754199, 1761754199),
(47989, 'Judges 20:18', 'Judges', 20, 18, 'اسراییلیان په بیت ییل کې د عبادت ځای ته لاړل او هلته یې د خدای څخه پوښتنه وکړه: «کومه قبیله به لومړی په بنیامینیانو باندې حمله کوي؟» څښتن په ځواب کې وویل: «د یهودا قبیله.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_18.mp3', '', 1761754199, 1761754199),
(47990, 'Judges 20:19', 'Judges', 20, 19, 'سبا سهار وختي اسراییلیان روان شول او د جبعې ښارګوټي ته نژدې یې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_19.mp3', '', 1761754199, 1761754199),
(47991, 'Judges 20:20', 'Judges', 20, 20, 'هغوی لاړل چې د بنیامین په لښکرو باندې حمله وکړي او جبعې ته مخامخ یې د جګړې دپاره سنګرونه ونیول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_20.mp3', '', 1761754199, 1761754199),
(47992, 'Judges 20:21', 'Judges', 20, 21, 'د بنیامین لښکر د ښارګوټي څخه راووت او په هغه ورځ یې د جګړې په ډګر کې دوه ویشت زره اسراییلیان ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_21.mp3', '', 1761754199, 1761754199),
(47993, 'Judges 20:24', 'Judges', 20, 24, 'نو اسراییلیان د دوهم ځل دپاره ووتل چې د بنیامینیانو د عسکرو په وړاندې وجنګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_24.mp3', '', 1761754199, 1761754199),
(47994, 'Judges 20:25', 'Judges', 20, 25, 'په هماغه ورځ بنیامینیان د جبعې څخه راووتل او دا ځل یې اتلس زره روزل شوي اسراییلي عسکر ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_25.mp3', '', 1761754199, 1761754199),
(47995, 'Judges 20:26', 'Judges', 20, 26, 'بیا د اسراییلو ټول خلک بیت ییل ته لاړل او هلته یې وژړل. هغوی د څښتن په حضور کې کښېناستل، تر ماښامه پورې یې روژه ونیوله او څښتن ته یې سوځېدونکې او د سلامتۍ نذرانې وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_26.mp3', '', 1761754199, 1761754199),
(47996, 'Judges 20:29', 'Judges', 20, 29, 'نو اسراییلیانو د جبعې په شاوخوا کې کمین ونیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_29.mp3', '', 1761754199, 1761754199),
(47997, 'Judges 20:30', 'Judges', 20, 30, 'په درېمه ورځ هغوی د بنیامینیانو په وړاندې ووتل او د مخکې ځل په شان یې خپل عسکر جبعې ته مخامخ ځای په ځای کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_30.mp3', '', 1761754199, 1761754199),
(47998, 'Judges 20:31', 'Judges', 20, 31, 'بنیامینیان د هغوی سره د مقابلې دپاره راووتل. اسراییلیان په شا لاړل او بنیامینیان د هغوی پسې شول او د ښار څخه لېرې شول. هغوی د مخکې ځل په شان د اسراییلیانو په وژلو پیل وکړ. په بانډو او په هغو لارو باندې چې بیت ییل او جبعې ته تللې وې، دېرش تنه اسراییلیان ووژل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_31.mp3', '', 1761754199, 1761754199),
(47999, 'Judges 20:32', 'Judges', 20, 32, 'بنیامینیانو وویل: «مونږ هغوی ته د مخکې ځل په شان ماتې ورکړه.» خو اسراییلیانو داسې پلان جوړ کړی ؤ چې په شا لاړ شي او هغوی د ښارګوټي څخه لارو ته وباسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_32.mp3', '', 1761754199, 1761754199),
(48000, 'Judges 20:33', 'Judges', 20, 33, 'نو کله چې د اسراییلو اصلي لښکر په شا شو او په بعل تامار کې بیا سره راټول شول، نو هغه اسراییلیان چې د جبعې په لوېدیځ کې په کمین کې پټ وو د خپلو ځایونو څخه په منډه راووتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_33.mp3', '', 1761754199, 1761754199),
(48001, 'Judges 20:34', 'Judges', 20, 34, 'لس زرو ځانګړو کسانو چې د ټولو اسراییلو څخه غوره شوي وو په جبعې باندې حمله وکړه او جګړه ډېره سخته وه. بنیامینیان نه پوهېدل چې د هغوی بربادي نژدې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_34.mp3', '', 1761754199, 1761754199),
(48002, 'Judges 20:35', 'Judges', 20, 35, 'نو څښتن د اسراییلو سره مرسته وکړه چې بنیامینیانو ته ماتې ورکړي. په هغه ورځ اسراییلیانو پنځه ویشت زره او سل تنه ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_35.mp3', '', 1761754199, 1761754199),
(48003, 'Judges 20:36', 'Judges', 20, 36, 'نو بنیامینیان پوه شول چې هغوی ماتې خوړلې ده. د اسراییلیانو د جګړې ګټل د اسراییلیانو د لښکرو اصلي ډله د بنیامینیانو څخه بېرته په شا لاړله، ځکه چې هغوی په خپلو کسانو باندې چې د جبعې په شاوخوا کې یې کمین نیولی ؤ، تکیه درلودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_36.mp3', '', 1761754199, 1761754199),
(48004, 'Judges 20:37', 'Judges', 20, 37, 'بیا هغو کسانو چې په کمین کې وو د هرې خوا څخه په جبعې باندې حمله وکړه او د هغه ښارګوټي ټول اوسېدونکي یې ووژل او ښار ته یې اور واچاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_37.mp3', '', 1761754199, 1761754199),
(48005, 'Judges 20:38', 'Judges', 20, 38, 'د اسراییلو اصلي لښکر او هغه پټ شویو کسانو په خپل منځ کې یوه نښه ټاکلې وه. کله چې هغوی زیات لوګي ولیدل چې د ښارګوټي څخه پورته کیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_38.mp3', '', 1761754199, 1761754199),
(48006, 'Judges 20:39', 'Judges', 20, 39, 'نو کوم اسراییلیان چې د ښارګوټي څخه دباندې وو هغه به راګرځي او په بنیامینیانو باندې به حمله کوي. تر دغه وخته پورې بنیامینیانو دېرش تنه اسراییلیان وژلي وو. هغوی د خپلو ځانونو سره ویل: «هو، مونږ هغوی ته د مخکې ځل په شان ماتې ورکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_39.mp3', '', 1761754199, 1761754199),
(48007, 'Judges 20:40', 'Judges', 20, 40, 'خو کله چې بنیامینیانو شاته وکتل او ویې لیدل چې د ښارګوټي له هرې خوا څخه اسمان ته لوګی پورته کیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_40.mp3', '', 1761754199, 1761754199),
(48008, 'Judges 20:41', 'Judges', 20, 41, 'نو بیا اسراییلیان راوګرځېدل او په هغوی باندې یې حمله وکړه. بنیامینیان پوه شول چې یوه بلا ورباندې راتلونکې ده، نو هغوی وارخطا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_41.mp3', '', 1761754199, 1761754199),
(48009, 'Judges 20:42', 'Judges', 20, 42, 'هغوی د اسراییلیانو څخه په شا لاړل او د دښتې خواته په منډو شول، خو ویې نه شو کولای چې وتښتي. هغوی د اصلي لښکر او هغو کسانو ترمنځ راګېر شول چې د ښارګوټي څخه راوتل، نو هغوی له منځه لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_42.mp3', '', 1761754199, 1761754199),
(48010, 'Judges 20:43', 'Judges', 20, 43, 'اسراییلیانو بنیامینیان کلابند کړل او په دوامداره توګه یې د جبعې تر ختیځه پورې تعقیب کړل او په لاره کې یې ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_43.mp3', '', 1761754199, 1761754199);